<?php
declare(strict_types=1);
require_once __DIR__ . '/functions.php';
require_login();
$pdo=db();$uid=(int)current_user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
 if($action==='read_all'){$q=$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?');$q->execute([$uid]);flash('success','All notifications marked as read.');}
 elseif($action==='read'&&$id>0){$q=$pdo->prepare('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?');$q->execute([$id,$uid]);flash('success','Notification marked as read.');}
 elseif($action==='unread'&&$id>0){$q=$pdo->prepare('UPDATE notifications SET is_read=0 WHERE id=? AND user_id=?');$q->execute([$id,$uid]);flash('success','Notification marked as unread.');}
 elseif($action==='delete'&&$id>0){$q=$pdo->prepare('DELETE FROM notifications WHERE id=? AND user_id=?');$q->execute([$id,$uid]);flash('success','Notification removed.');}
 header('Location: notifications.php?filter='.rawurlencode((string)($_POST['filter']??'all')));exit;
}
$filter=(string)($_GET['filter']??'all');if(!in_array($filter,['all','unread','alerts'],true))$filter='all';
$conditions=['user_id=?'];$params=[$uid];if($filter==='unread'){$conditions[]='is_read=0';}elseif($filter==='alerts'){$conditions[]="type='alert'";}
$q=$pdo->prepare('SELECT id,title,message,type,is_read,created_at FROM notifications WHERE '.implode(' AND ',$conditions).' ORDER BY created_at DESC LIMIT 150');$q->execute($params);$items=$q->fetchAll();
$count=$pdo->prepare('SELECT COUNT(*) total,SUM(is_read=0) unread,SUM(type="alert") alerts FROM notifications WHERE user_id=?');$count->execute([$uid]);$counts=$count->fetch();
page_start('Notifications','notifications.php');
?>
<div class="page-heading"><div><p class="overline">STAY IN THE LOOP</p><h1>Notifications</h1><p class="heading-subtitle">Attendance alerts, class reminders, and account updates.</p></div><?php if((int)$counts['unread']>0): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="read_all"><input type="hidden" name="filter" value="<?= e($filter) ?>"><button class="btn btn-outline-secondary mark-all"><i class="bi bi-check2-all me-1"></i>Mark all as read</button></form><?php endif; ?></div>
<section class="content-card notifications-card"><div class="card-heading"><div><h2>Your updates <span class="count-bubble"><?= number_format((int)$counts['total']) ?></span></h2><p><?= number_format((int)$counts['unread']) ?> unread · <?= number_format((int)$counts['alerts']) ?> attendance alerts</p></div><span class="notification-bell"><i class="bi bi-bell"></i></span></div><nav class="filter-tabs"><a class="<?= $filter==='all'?'active':'' ?>" href="?filter=all">All <span><?= (int)$counts['total'] ?></span></a><a class="<?= $filter==='unread'?'active':'' ?>" href="?filter=unread">Unread <span><?= (int)$counts['unread'] ?></span></a><a class="<?= $filter==='alerts'?'active':'' ?>" href="?filter=alerts">Attendance alerts <span><?= (int)$counts['alerts'] ?></span></a></nav><div class="notification-list">
<?php if(!$items): ?><div class="notification-empty"><span><i class="bi bi-bell-slash"></i></span><strong><?= $filter==='unread'?'You’re all caught up':'No notifications here yet' ?></strong><p>New announcements and attendance reminders will show up here.</p></div><?php else: foreach($items as $item): $icon=$item['type']==='alert'?'bi-exclamation-triangle':($item['type']==='success'?'bi-check2-circle':'bi-info-circle'); ?><article class="notification-item <?= (int)$item['is_read']?'is-read':'is-unread' ?>"><div class="notification-symbol type-<?= e($item['type']) ?>"><i class="bi <?= e($icon) ?>"></i></div><div class="notification-copy"><h3><?= e($item['title']) ?></h3><p><?= nl2br(e($item['message'])) ?></p><span><i class="bi bi-clock me-1"></i><?= e(date('M j, Y · g:i A',strtotime($item['created_at']))) ?> · <?= e(ucfirst($item['type'])) ?></span></div><div class="notification-actions"><?php if(!(int)$item['is_read']): ?><span class="unread-dot" title="Unread"></span><?php endif; ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="filter" value="<?= e($filter) ?>"><input type="hidden" name="action" value="<?= (int)$item['is_read']?'unread':'read' ?>"><button class="notification-toggle" title="<?= (int)$item['is_read']?'Mark unread':'Mark read' ?>" aria-label="<?= (int)$item['is_read']?'Mark unread':'Mark read' ?>"><i class="bi <?= (int)$item['is_read']?'bi-arrow-counterclockwise':'bi-check2' ?>"></i></button></form><form method="post" onsubmit="return confirm('Delete this notification?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="filter" value="<?= e($filter) ?>"><input type="hidden" name="action" value="delete"><button class="notification-toggle" title="Delete notification" aria-label="Delete notification"><i class="bi bi-trash3"></i></button></form></div></article><?php endforeach; endif; ?>
</div></section>
<?php page_end(); ?>
